const { withAndroidManifest } = require('expo/config-plugins');

/**
 * Declares the USB host feature used by `modules/tspl-usb-printer`.
 *
 * Android requires an app that calls the USB host API to declare the feature,
 * and vendor ROMs enforce it: on the Gertec SK-210 (MediaTek, Android 13) the
 * system enumerated the label printer — `dumpsys usb` listed 0x0FE6:0x9900 —
 * while `usbManager.deviceList` came back empty, so the check-in screen kept
 * reporting "sem impressora". `android/` is generated by prebuild, so this has
 * to be a config plugin; editing the manifest by hand does not survive.
 *
 * `required="false"` keeps the app installable on a phone with no USB host,
 * which is every device the operators carry — printing is the totem's job.
 */
const USB_HOST_FEATURE = 'android.hardware.usb.host';

module.exports = function withUsbHost(config) {
  return withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults.manifest;
    manifest['uses-feature'] = manifest['uses-feature'] ?? [];

    const alreadyThere = manifest['uses-feature'].some(
      (feature) => feature.$?.['android:name'] === USB_HOST_FEATURE,
    );

    if (!alreadyThere) {
      manifest['uses-feature'].push({
        $: { 'android:name': USB_HOST_FEATURE, 'android:required': 'false' },
      });
    }

    return cfg;
  });
};
